;(function(){
'use strict';
if(typeof document==='undefined')return;
const flags={"zh":"data:image/png;base64,","tr":"data:image/png;base64,","ru":"data:image/png;base64,","ky":"data:image/png;base64,","uz":"data:image/png;base64,","tg":"data:image/png;base64,","kk":"data:image/png;base64,","tk":"data:image/png;base64,","en":"data:image/png;base64,"};
function init(){
 const select=document.getElementById('languageSelect');
 if(!select||select.dataset.flagPickerReady)return;
 const options=Array.from(select.options);
 if(!options.length||!options.every(option=>flags[option.value]))return;
 const style=document.createElement('style');
 style.textContent='.flag-picker{position:relative;display:inline-block;z-index:20}.flag-picker summary{list-style:none;cursor:pointer;background:#eef5fc;color:#07549b;border-radius:8px;padding:7px 10px;display:flex;align-items:center;gap:7px;font-size:14px;font-weight:700;min-height:32px;box-sizing:border-box}.flag-picker summary::-webkit-details-marker{display:none}.flag-picker summary:after{content:"▾";font-size:12px}.flag-picker img{width:24px;height:18px;object-fit:contain;flex:none}.flag-picker-menu{position:absolute;right:0;top:calc(100% + 5px);background:white;border:1px solid #d7e3ee;border-radius:10px;box-shadow:0 4px 18px #0003;padding:4px;min-width:155px;max-height:75vh;overflow-y:auto}.flag-picker-menu button{width:100%;display:flex;align-items:center;gap:8px;text-align:left;padding:8px;border:0;background:white;color:#17354b;border-radius:6px;font-size:14px;cursor:pointer}.flag-picker-menu button:hover,.flag-picker-menu button:focus-visible{background:#e7f1fa;outline:2px solid #07549b}';
 document.head.appendChild(style);
 const details=document.createElement('details');details.className='flag-picker';
 const summary=document.createElement('summary');summary.setAttribute('aria-label','Language / Язык');
 const image=document.createElement('img');image.alt='';
 const label=document.createElement('span');summary.append(image,label);
 const menu=document.createElement('div');menu.className='flag-picker-menu';
 const names={};
 for(const option of options){
  const name=option.textContent.replace(/^[\u{1F1E6}-\u{1F1FF}]+\s*/u,'');
  names[option.value]=name;
  const button=document.createElement('button');button.type='button';button.dataset.lang=option.value;
  const icon=document.createElement('img');icon.alt='';icon.src=flags[option.value];
  const text=document.createElement('span');text.textContent=name;button.append(icon,text);
  button.addEventListener('click',()=>{select.value=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));update();details.open=false;summary.focus();});
  menu.appendChild(button);
 }
 function update(){const value=select.value;image.src=flags[value]||flags.tr;label.textContent=names[value]||names.tr;}
 select.addEventListener('change',update);
 details.append(summary,menu);select.insertAdjacentElement('afterend',details);
 select.hidden=true;select.dataset.flagPickerReady='true';update();
 document.addEventListener('click',e=>{if(!details.contains(e.target))details.open=false;});
 details.addEventListener('keydown',e=>{if(e.key==='Escape'&&details.open){details.open=false;summary.focus();}});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
